const CACHE_NAME="my-cache-v1",ASSETS_TO_CACHE=["/","/index.html","/styles.css","/studies.html"],CACHE_PATTERNS=["/api/","/images/","product","vendor"],NETWORK_FIRST_EXTENSIONS=/\.(js|css|html|woff2)(\?.*)?$/i;function shouldCacheUrl(e){return CACHE_PATTERNS.some(t=>e.includes(t))}function isNetworkFirstAsset(e){const t=new URL(e);return NETWORK_FIRST_EXTENSIONS.test(t.pathname)||t.pathname.endsWith("/")}self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>(console.log("[Cache Worker] Caching app shell"),e.addAll(ASSETS_TO_CACHE))))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(e!==CACHE_NAME)return console.log("[Cache Worker] Deleting old cache:",e),caches.delete(e)}))))}),self.addEventListener("fetch",e=>{"GET"===e.request.method&&(isNetworkFirstAsset(e.request.url)?e.respondWith(caches.open(CACHE_NAME).then(t=>fetch(e.request).then(s=>(s&&200===s.status&&t.put(e.request,s.clone()),s)).catch(()=>t.match(e.request)))):shouldCacheUrl(e.request.url)?e.respondWith(caches.open(CACHE_NAME).then(t=>t.match(e.request).then(s=>{const n=fetch(e.request).then(s=>(s&&200===s.status&&t.put(e.request,s.clone()),s)).catch(()=>{});return s||n}))):e.respondWith(caches.match(e.request).then(t=>t||fetch(e.request))))});
